# frozen_string_literal: true

require "minitest/autorun"
require "minitest/mock"
require_relative "../../fastlane/apple_distribution_key"

# Inert OpenSSL doubles ONLY. Every frame call replaces RSA.generate and
# PKey.read; no private key/CSR is actually generated by these local tests.
class AppleDistributionKeyTest < Minitest::Test
  Producer = MRKAppleDistributionKey
  PRIVATE = "SYNTHETIC-NOT-PKCS8".b.freeze
  PUBLIC = "SYNTHETIC-NOT-SPKI".b.freeze
  REQUEST = "-----BEGIN CERTIFICATE REQUEST-----\nMAA=\n-----END CERTIFICATE REQUEST-----\n".freeze

  class FakeRSA < OpenSSL::PKey::RSA
    attr_accessor :bits, :exponent, :public_der, :private_der, :proof_valid
    attr_reader :owned_private

    def initialize(private_key)
      @private_key, @bits, @exponent = private_key, 2048, 65_537
      @public_der, @private_der = PUBLIC, PRIVATE
      @proof_valid = true
    end

    def private? = @private_key
    def n = Struct.new(:num_bits).new(@bits)
    def e = Struct.new(:to_i).new(@exponent)
    def public_to_der = @public_der.dup
    def private_to_der
      @owned_private = @private_der.dup
    end
    def sign(digest, value)
      raise "Unexpected synthetic private operation" unless @private_key && digest.name == "SHA256" && value == Producer::KEY_CHECK
      "S" * 256
    end
    def verify(digest, signature, value)
      !@private_key && @proof_valid && digest.name == "SHA256" && signature == "S" * 256 && value == Producer::KEY_CHECK
    end
  end

  class FakeRequest
    attr_accessor :version, :subject, :public_key, :attributes, :verified, :signature_algorithm
    attr_reader :sign_key, :digest

    def initialize(public_key)
      @version, @subject, @public_key = 0, Producer.subject, public_key
      @attributes, @verified = [], true
      @signature_algorithm = "sha256WithRSAEncryption"
    end

    def sign(key, digest)
      @sign_key, @digest = key, digest.name
    end
    def to_pem = REQUEST.dup
    def verify(key) = @verified && key.equal?(@public_key)
  end

  def with_fake(producer_error: nil)
    private_key, public_key, parsed = FakeRSA.new(true), FakeRSA.new(false), FakeRSA.new(true)
    created, verified = FakeRequest.new(public_key), FakeRequest.new(public_key)
    calls = []
    generate = lambda do |bits, exponent|
      calls << [bits, exponent]
      raise producer_error if producer_error
      private_key
    end
    parse = lambda do |value|
      case value
      when PUBLIC then public_key
      when PRIVATE then parsed
      else raise "Unexpected private fixture input"
      end
    end
    request = lambda do |value = nil|
      raise "Unexpected CSR fixture input" unless value.nil? || value == REQUEST
      value.nil? ? created : verified
    end
    OpenSSL::PKey::RSA.stub(:generate, generate) do
      OpenSSL::PKey.stub(:read, parse) do
        OpenSSL::X509::Request.stub(:new, request) do
          yield private_key, public_key, parsed, created, verified, calls
        end
      end
    end
  end

  def private_frame
    Producer::MAGIC + [PRIVATE.bytesize, REQUEST.bytesize, PUBLIC.bytesize].pack("NNN") + PRIVATE + REQUEST + PUBLIC
  end

  class FakeInput
    Stat = Struct.new(:dev, :ino, :mode, :uid, :gid, :nlink, :size, :mtime, :ctime) do
      def file? = true
    end
    attr_accessor :mode, :links, :changed, :closed
    attr_reader :owned
    def initialize(bytes)
      @bytes, @mode, @links, @reads, @changed, @closed = bytes, 0o100600, 1, 0, false, false
    end
    def stat
      Stat.new(17, @changed && @reads > 0 ? 19 : 18, @mode, Process.euid, Process.egid, @links,
               @bytes.bytesize, Time.at(100), Time.at(100))
    end
    def read(maximum)
      @reads += 1
      return nil if @reads > 1
      raise "Unexpected unbounded private read" unless maximum == Producer::PRIVATE_LIMIT + 1
      @owned = @bytes.dup
    end
  end

  def verify_file(file, close_failed: false)
    writes = []
    opener = lambda do |path, flags, &body|
      assert_equal "/native-fixture/pending-apple-key.mrk", path
      assert_equal File::RDONLY | File::NOFOLLOW, flags
      body.call(file)
      file.closed = true
      raise IOError, "SYNTHETIC_PRIVATE_CLOSE_DETAIL" if close_failed
    end
    result = nil
    File.stub(:open, opener) do
      STDOUT.stub(:write, lambda { |bytes|
        assert file.closed
        writes << bytes.dup
        bytes.bytesize
      }) do
        STDERR.stub(:write, ->(*) { flunk "verifier must not log private input/error" }) do
          result = Producer.verify_main(["/native-fixture/pending-apple-key.mrk"])
        end
      end
    end
    [result, writes]
  end

  def test_one_fixed_local_generation_and_verified_csr_private_binary_frame
    with_fake do |key, _public_key, parsed, request, _verified, calls|
      frame = Producer.frame
      assert_equal [[2048, 65_537]], calls
      assert_same key, request.sign_key
      assert_equal "SHA256", request.digest
      assert_equal 0, request.version
      assert_equal [["CN", Producer::SUBJECT]], request.subject.to_a.map { |entry| entry.first(2) }
      assert_equal Producer.subject.to_der, request.subject.to_der
      assert frame.start_with?(Producer::MAGIC)
      offset = Producer::MAGIC.bytesize
      assert_equal [PRIVATE.bytesize, REQUEST.bytesize, PUBLIC.bytesize], frame.byteslice(offset, 12).unpack("NNN")
      assert_equal PRIVATE + REQUEST + PUBLIC, frame.byteslice(offset + 12..)
      assert_empty key.owned_private # Only the owned temporary, not OpenSSL heap.
      assert_empty parsed.owned_private
    end
  end

  def test_entropy_failure_is_one_attempt_with_no_fallback_or_error_disclosure
    with_fake(producer_error: RuntimeError.new("SYNTHETIC_PRIVATE_ENTROPY_DETAIL")) do |_key, _public, _parsed, _req, _verified, calls|
      writes = []
      STDOUT.stub(:write, ->(bytes) { writes << bytes; bytes.bytesize }) do
        STDERR.stub(:write, ->(*) { flunk "must not log private producer errors" }) do
          assert_equal 1, Producer.main([])
        end
      end
      assert_equal [[2048, 65_537]], calls
      assert_empty writes
    end
  end

  def test_csr_signature_or_public_key_mismatch_never_returns_a_candidate
    with_fake do |_key, _public, _parsed, _req, verified, calls|
      verified.verified = false
      error = assert_raises(ArgumentError) { Producer.frame }
      assert_equal "Apple signing key preparation refused", error.message
      assert_equal 1, calls.length
    end
    with_fake do |_key, _public, parsed, _req, _verified, calls|
      parsed.public_der = "wrong-public-key"
      assert_raises(ArgumentError) { Producer.frame }
      assert_equal 1, calls.length
    end
  end

  def test_wrong_key_profile_attributes_and_oversize_are_refused_not_normalized
    [[:bits, 1024], [:exponent, 3], [:private_der, "X" * (Producer::KEY_LIMIT + 1)],
     [:public_der, "X" * (Producer::SPKI_LIMIT + 1)]].each do |name, value|
      with_fake do |key, _public, _parsed, _req, _verified, calls|
        key.public_send("#{name}=", value)
        assert_raises(ArgumentError) { Producer.frame }
        assert_equal 1, calls.length
      end
    end
    with_fake do |_key, _public, _parsed, _req, verified, calls|
      verified.attributes = ["unrequested-extension"]
      assert_raises(ArgumentError) { Producer.frame }
      assert_equal 1, calls.length
    end
  end

  def test_argv_options_never_select_path_algorithm_or_private_value
    with_fake do |_key, _public, _parsed, _req, _verified, calls|
      [%w[--output /tmp/synthetic-key], %w[--bits 4096], ["SYNTHETIC_PASSWORD"]].each do |args|
        assert_equal 1, Producer.main(args)
      end
      assert_empty calls
    end
  end

  def test_private_write_failure_reports_failure_without_second_generation
    with_fake do |_key, _public, _parsed, _req, _verified, calls|
      writes = []
      STDOUT.stub(:write, ->(bytes) { writes << bytes.dup; bytes.bytesize - 1 }) do
        STDERR.stub(:write, ->(*) { flunk "private write error must stay redacted" }) do
          assert_equal 1, Producer.main([])
        end
      end
      assert_equal 1, calls.length
      assert_equal 1, writes.length
      assert writes[0].start_with?(Producer::MAGIC)
      # Partial output is retained by the real native receive, not retried or
      # credited as a saved key. This double proves no native finality.
    end
  end

  def test_restore_verification_is_same_private_key_csr_and_spki_without_generation
    with_fake do |_key, _public, parsed, _req, _verified, calls|
      original = private_frame
      result = Producer.public_frame(original)
      assert_empty calls
      assert_equal private_frame, original # The real owner retains original input.
      assert_equal Producer::PUBLIC_MAGIC + [REQUEST.bytesize, PUBLIC.bytesize].pack("NN") + REQUEST + PUBLIC, result
      refute_includes result, PRIVATE
      assert_empty parsed.owned_private
      file = FakeInput.new(original)
      status, writes = verify_file(file)
      assert_equal 0, status
      assert_equal [result], writes
      assert_empty file.owned
      assert_empty calls
    end
  end

  def test_restore_does_not_treat_a_valid_csr_as_proof_of_private_key_usability
    with_fake do |_key, public_key, _parsed, _req, _verified, calls|
      public_key.proof_valid = false
      assert_raises(ArgumentError) { Producer.public_frame(private_frame) }
      assert_empty calls
    end
    with_fake do |_key, _public, _parsed, _req, verified, calls|
      verified.signature_algorithm = "sha512WithRSAEncryption"
      assert_raises(ArgumentError) { Producer.public_frame(private_frame) }
      assert_empty calls
    end
    with_fake do |_key, _public, _parsed, _req, _verified, calls|
      [private_frame + "trailing", private_frame.sub(Producer::MAGIC, "bad"),
       Producer::MAGIC + [Producer::KEY_LIMIT + 1, 1, 1].pack("NNN") + "XXX"].each do |value|
        assert_raises(ArgumentError) { Producer.public_frame(value) }
      end
      assert_empty calls
    end
  end

  def test_restore_input_change_permissions_or_original_close_failure_never_discloses_public_output
    with_fake do |_key, _public, _parsed, _req, _verified, calls|
      [[:mode, 0o100644], [:links, 2], [:changed, true]].each do |name, value|
        file = FakeInput.new(private_frame)
        file.public_send("#{name}=", value)
        status, writes = verify_file(file)
        assert_equal 1, status
        assert_empty writes
        assert_empty file.owned if file.owned
      end
      file = FakeInput.new(private_frame)
      status, writes = verify_file(file, close_failed: true)
      assert_equal 1, status
      assert_empty writes
      assert_empty file.owned
      assert_empty calls
    end
  end
end
